class Tumpukan<T> {
  private isi: T[] = [];
  taruh(x: T): void {
    this.isi.push(x);
  }
  ambil(): T | undefined {
    return this.isi.pop();
  }
  get jumlah(): number {
    return this.isi.length;
  }
}
const piring = new Tumpukan<string>();
piring.taruh("A");
piring.taruh("B");
piring.taruh("C");
console.log(piring.ambil(), piring.ambil());
console.log("Sisa:", piring.jumlah);
